#include <cstdio>
#include <vector>
using namespace std;

/*
  Estrategia:
  - Um turno com parametro T transforma a posicao q (q nao multiplo de T) numa lista
    na nova posicao v = q - floor(q/T) (bijecao entre nao-multiplos e posicoes remanescentes).
  - Logo, dado v, a posicao anterior unica e q = v + floor((v-1)/(T-1)) (a v-esima posicao
    que nao e multiplo de T).
  - Calculamos o numero total de sobreviventes s aplicando s <- s - floor(s/T) a cada turno.
  - A resposta e a lista final: para cada j = 1..min(10000, s), a posicao inicial do
    j-esimo sobrevivente e obtida aplicando a inversao dos turnos na ordem reversa.
    O mapeamento e estritamente crescente em j, logo a saida ja sai ordenada.
*/

int main(){
    long long N, M;
    if(scanf("%lld %lld", &N, &M) != 2) return 0;

    vector<unsigned> T((size_t)M);
    long long s = N;                         // tamanho da lista corrente
    for(long long i = 0; i < M; ++i){
        unsigned t;
        scanf("%u", &t);
        T[(size_t)i] = t;
        s -= s / (long long)t;               // remove floor(s/T) elementos
    }

    unsigned K = (s < 10000) ? (unsigned)s : 10000u;

    vector<unsigned> v((size_t)K + 1);
    for(unsigned j = 1; j <= K; ++j) v[j] = j;   // posicoes finais 1..K

    for(long long i = M - 1; i >= 0; --i){
        unsigned Ti = T[(size_t)i];
        if(v[(size_t)K] < Ti) continue;          // nenhum valor muda neste turno
        unsigned step = Ti - 1;
        if(step == 1){                            // T = 2: q = 2*v - 1
            for(unsigned t = 1; t <= K; ++t)
                v[t] += v[t] - 1;
        } else {
            for(unsigned t = 1; t <= K; ++t){
                unsigned x = v[t];
                v[t] = x + (x - 1) / step;
            }
        }
    }

    for(unsigned t = 1; t <= K; ++t)
        printf("%u\n", v[t]);

    return 0;
}
